package com.aistock.prediction.explanation;
import com.aistock.prediction.forecast.*;import com.aistock.prediction.verification.VerificationQueryRepository;import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.Clock;import java.util.UUID;
public final class ExplanationService {
 private final ForecastRepository forecasts;private final VerificationQueryRepository verifications;private final ExplanationRepository repository;private final MaasClient client;private final ObjectMapper mapper;private final Clock clock;
 public ExplanationService(ForecastRepository forecasts,VerificationQueryRepository verifications,ExplanationRepository repository,MaasClient client,ObjectMapper mapper,Clock clock){this.forecasts=forecasts;this.verifications=verifications;this.repository=repository;this.client=client;this.mapper=mapper;this.clock=clock;}
 private ExplanationFacts.Facts facts(UUID user,UUID prediction){var record=forecasts.get(user,prediction);if(!"SUCCEEDED".equals(record.state())||record.snapshot()==null)throw ExplanationFacts.invalid();return ExplanationFacts.build(prediction,record.snapshot(),record.modelSnapshot(),verifications.list(user,prediction,1).path("current"),client.model(),mapper);}
 public JsonNode get(UUID user,UUID prediction){var facts=facts(user,prediction);var view=(ObjectNode)repository.read(user,prediction,facts.hash(),clock.instant());view.put("configured",client.enabled());if(view.path("latest").isObject())((ObjectNode)view.path("latest")).put("needsReview",!ExplanationFacts.supportsSavedPrompt(view.path("latest").path("context").path("promptVersion").asText()));return view;}
 public JsonNode generate(UUID user,UUID prediction,UUID operation){var facts=facts(user,prediction);if(!client.enabled())throw HttpMaasClient.error("AI_NOT_CONFIGURED");var claim=repository.claim(user,prediction,operation,facts,clock.instant());if(!claim.execute())return claim.receipt();JsonNode paragraphs=null;String failure=null;try{paragraphs=ExplanationTemplate.render(client.generate(facts.values()),facts.values(),mapper);}catch(BusinessException e){failure=e.code();}catch(RuntimeException e){failure="AI_UNAVAILABLE";}return repository.complete(operation,paragraphs,failure,clock.instant());}
}
